package io.github.diodeme.ji.testkit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

final class FixtureRunnerTest {
    @Test
    void readsEveryPinnedPiDomainIndependently() throws Exception {
        Path root = Path.of("../../../contracts/fixtures");
        var manifest = new ObjectMapper().readTree(root.resolve("manifest.json").toFile());
        assertEquals(5, manifest.path("fixtures").size());
        for (var fixture : manifest.path("fixtures")) {
            var normalized = FixtureRunner.normalize(root.resolve(fixture.path("path").asText()));
            assertEquals("ji-pi-projection-v1", normalized.path("schemaVersion").asText());
            assertEquals(fixture.path("domain").asText(), normalized.path("domain").asText());
            assertEquals(
                    new ObjectMapper().readTree(root.resolve(fixture.path("expectedPath").asText()).toFile()),
                    normalized);
        }
    }

    @Test
    void rejectsNonContiguousAttempts() throws Exception {
        try (TemporaryWorkspace workspace = TemporaryWorkspace.create()) {
            Path fixture = workspace.resolve("invalid.json");
            Files.writeString(fixture, """
                    {"fixtureId":"invalid","items":[
                      {"seq":1,"kind":"record","type":"operation_started","id":"start","runId":"run-1","timestamp":1,"data":{}},
                      {"seq":2,"kind":"record","type":"step_attempt","id":"attempt","runId":"run-1","timestamp":2,"data":{"step":"assistant","attempt":2}}
                    ]}
                    """);
            assertThrows(IllegalArgumentException.class, () -> FixtureRunner.normalize(fixture));
        }
    }
}

